package com.example.Tech.dto.request.user;

import com.example.Tech.util.AccountUtil;
import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/** A new administrator account (POST /admin/users/admins). The password is generated by the server. */
public record AdminCreateRequest(

        @Schema(example = "quan.tri@poy.vn")
        @NotBlank(message = "Vui lòng nhập email")
        @Email(message = "Email chưa đúng định dạng")
        @Size(max = 120, message = "Email tối đa 120 ký tự")
        String email,

        @Schema(example = "quan.tri")
        @NotBlank(message = "Vui lòng nhập tên đăng nhập")
        @Size(min = 3, max = 50, message = "Tên đăng nhập từ 3 đến 50 ký tự")
        @Pattern(regexp = AccountUtil.USERNAME_REGEX, message = "Tên đăng nhập chỉ gồm chữ, số, dấu chấm, gạch dưới và gạch ngang")
        String username,

        @Schema(example = "Nguyễn Quản Trị")
        @NotBlank(message = "Vui lòng nhập họ tên")
        @Size(max = 120, message = "Họ tên tối đa 120 ký tự")
        String fullname,

        @Schema(example = "0901234567")
        @Size(max = 20, message = "Số điện thoại tối đa 20 ký tự")
        String phone
) {
}
